// ```yaml
// apiVersion: auth0.planton.dev/v1alpha1
// kind: Auth0PromptScreenPartials
// metadata:
//
//	name: signup-partials
//	org: my-organization
//
// spec:
//
//	promptType: signup
//	screenPartials:
